public static int countUpper(String str) {
    int count = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c >= 'A' && c <= 'Z') {
            count++;
        }
    }
    return count;
}

public static String removeSpaces(String str) {
    String result = "";
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) != ' ') {
            result = result + str.charAt(i);
        }
    }
    return result;
}

public static int CountUpper(string str)
{
    int count = 0;
    for (int i = 0; i < str.Length; i++)
    {
        char c = str[i];
        if (c >= 'A' && c <= 'Z')
        {
            count++;
        }
    }
    return count;
}

public static string RemoveSpaces(string str)
{
    string result = "";
